import{_ as e,c as t,ak as i,o}from"./chunks/framework.oXWZ3nXk.js";const p=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md"}'),r={name:"guide/index.md"};function n(s,a,l,c,d,h){return o(),t("div",null,a[0]||(a[0]=[i('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p>Welcome to the official documentation for <a href="https://github.com/mathflowjs/mathflow" target="_blank" rel="noreferrer">MathFlow</a>!</p><h2 id="what-is-mathflow" tabindex="-1">What is MathFlow? <a class="header-anchor" href="#what-is-mathflow" aria-label="Permalink to &quot;What is MathFlow?&quot;">​</a></h2><p><strong>MathFlow</strong> is a lightweight, expressive JavaScript library for mathematical expressions and calculations. It provides a simple, intuitive syntax for arithmetic, algebra, trigonometry, logarithms, and more.</p><h2 id="what-mathflow-is-not" tabindex="-1">What MathFlow is not <a class="header-anchor" href="#what-mathflow-is-not" aria-label="Permalink to &quot;What MathFlow is not&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">WARNING</p><ul><li>MathFlow is not a general-purpose programming language. It is focused on mathematical computation and basic scripting.</li></ul></div><h2 id="main-objectives" tabindex="-1">Main Objectives <a class="header-anchor" href="#main-objectives" aria-label="Permalink to &quot;Main Objectives&quot;">​</a></h2><p>MathFlow aims for <em>expressiveness</em>, <em>focus</em>, and <em>simplicity</em>, making it ideal for math-centric applications, calculators, and educational tools.</p><h2 id="how-it-works" tabindex="-1">How it Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it Works&quot;">​</a></h2><p>MathFlow exposes an <a href="./../api/">API</a> for evaluating code, solving equations, rendering, and more. The typical evaluation process:</p><ol><li>A global scope for variables is created.</li><li>Source code is split into statements, whitespace is trimmed, and composite terms like <code>2x</code> are expanded to <code>2*x</code>.</li><li>Variable declarations are executed and stored in the scope.</li><li>Each statement is tokenized, parsed into an AST, and interpreted.</li><li>The result of the last statement is returned, along with the final scope.</li></ol>',11)]))}const u=e(r,[["render",n]]);export{p as __pageData,u as default};
